from collections import deque

def infer_transform(g):
    h,w=len(g),len(g[0]); bg=max(set(x for row in g for x in row), key=lambda x:sum(row.count(x) for row in g))
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if g[r][c]==bg or (r,c) in seen: continue
        q=[(r,c)];seen.add((r,c)); comp=[]
        while q:
          x,y=q.pop();comp.append((x,y))
          for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]!=bg:
              seen.add((a,b));q.append((a,b))
        comps.append(comp)
    sprite=max(comps,key=len)
    sr0=min(r for r,c in sprite); sr1=max(r for r,c in sprite); sc0=min(c for r,c in sprite); sc1=max(c for r,c in sprite)
    sh,sw=sr1-sr0+1,sc1-sc0+1
    patch=[[bg]*sw for _ in range(sh)]
    for r,c in sprite: patch[r-sr0][c-sc0]=g[r][c]
    markers=[p[0] for p in comps if len(p)==1 and p is not sprite]
    # ids identity issue `p is not sprite`; okay comps list reference
    res=[row[:] for row in g]
    for r,c in markers:
      top,left=r-sh//2,c-sw//2
      for dr in range(sh):
       for dc in range(sw):
        rr,cc=top+dr,left+dc
        if 0<=rr<h and 0<=cc<w:res[rr][cc]=patch[dr][dc]
    return res, (bg,len(sprite),(sh,sw),markers,patch)
